CREATE OR REPLACE FUNCTION public.ca_club_members_win_loss(p_club_id uuid, p_user_ids uuid[], p_period text DEFAULT 'overall'::text)
 RETURNS TABLE(user_id uuid, cash numeric, mtt numeric, net numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_period text := lower(btrim(coalesce(p_period, 'overall')));
  v_chicago_today date := (now() AT TIME ZONE 'America/Chicago')::date;
  v_from date;
  v_start timestamptz;
  v_end timestamptz := (v_chicago_today + 1)::timestamp AT TIME ZONE 'America/Chicago';
BEGIN
  IF v_period NOT IN ('today', 'week', 'month', 'overall') THEN
    RAISE EXCEPTION 'Invalid win loss period' USING ERRCODE = '22023';
  END IF;
  IF coalesce(cardinality(p_user_ids), 0) > 100 THEN
    RAISE EXCEPTION 'At most 100 members per call' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.club_member_daily_facts_state WHERE singleton AND initialized)
  THEN RAISE EXCEPTION 'Member daily facts are not initialized'; END IF;

  -- Every period except Overall begins at 12:00 AM Chicago.
  v_from := CASE v_period
    WHEN 'today' THEN v_chicago_today
    WHEN 'week' THEN date_trunc('week', v_chicago_today::timestamp)::date
    WHEN 'month' THEN date_trunc('month', v_chicago_today::timestamp)::date
    ELSE NULL END;
  v_start := v_from::timestamp AT TIME ZONE 'America/Chicago';

  RETURN QUERY
  WITH asked AS (
    SELECT DISTINCT u AS uid FROM unnest(coalesce(p_user_ids, ARRAY[]::uuid[])) u WHERE u IS NOT NULL
  ), allowed AS (
    SELECT a.uid FROM asked a
     WHERE public.ca_club_roster_access(p_club_id, a.uid) IN ('staff', 'downline', 'service')
  ), cash AS (
    SELECT al.uid,
           CASE WHEN v_period = 'today' THEN
             public.ca_club_member_chicago_today_cash(p_club_id, al.uid)
           WHEN v_from IS NULL THEN
             (SELECT coalesce(sum(t.net) FILTER(WHERE NOT t.is_mtt), 0) FROM (SELECT 1) anchor
                LEFT JOIN public.ca_member_record_daily_facts(p_club_id,al.uid,NULL,NULL) t
                  ON t.club_id = p_club_id AND t.user_id = al.uid)
           ELSE
             public.ca_club_member_chicago_cash(p_club_id, al.uid, v_from, v_chicago_today + 1)
           END AS cash_net
      FROM allowed al
  )
  SELECT c.uid,
         round(c.cash_net, 2),
         round(m.mtt_net, 2),
         round(c.cash_net + m.mtt_net, 2)
    FROM cash c
    CROSS JOIN LATERAL (
      SELECT public.ca_club_member_tournament_money(
        p_club_id, c.uid,
        CASE WHEN v_from IS NULL THEN NULL ELSE v_start END,
        CASE WHEN v_period = 'today' THEN v_end ELSE NULL END) AS mtt_net
    ) m;
END;
$function$

CREATE OR REPLACE FUNCTION public.ca_club_roster_access(p_club_id uuid, p_target_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_service boolean := COALESCE(auth.role(), 'service_role') = 'service_role';
BEGIN
  IF p_club_id IS NULL OR p_target_user_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.club_members target
     WHERE target.user_id = p_target_user_id AND target.club_id = p_club_id
       AND COALESCE(target.status, 'approved') IN ('active', 'approved')
  ) THEN RETURN 'none'; END IF;
  IF v_service THEN RETURN 'service'; END IF;
  IF v_actor IS NULL THEN RETURN 'none'; END IF;
  IF public.fn_club_cashier_scope(p_club_id) = 'downline'
     AND NOT public.fn_can_read_club_member_data(p_club_id,p_target_user_id) THEN RETURN 'none'; END IF;
  IF EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = v_actor AND COALESCE(p.is_admin, false))
     OR COALESCE(public.fn_is_union_overseer(p_club_id, v_actor), false)
  THEN RETURN 'staff'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.club_members actor
     WHERE actor.user_id = v_actor AND actor.club_id = p_club_id
       AND actor.role IN ('owner','co_owner','admin')
       AND COALESCE(actor.status, 'approved') IN ('active','approved')
  ) THEN RETURN 'staff'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.club_members actor
     WHERE actor.user_id = v_actor AND actor.club_id = p_club_id
       AND actor.role IN ('super_agent','agent','sub_agent')
       AND COALESCE(actor.status, 'approved') IN ('active','approved')
  ) THEN
    IF p_target_user_id = v_actor THEN RETURN 'downline'; END IF;
    IF EXISTS (
      WITH RECURSIVE edges AS (
        SELECT cm.agent_id parent, cm.user_id child
          FROM public.club_members cm
         WHERE cm.club_id = p_club_id AND cm.agent_id IS NOT NULL
           AND cm.agent_id <> cm.user_id
           AND COALESCE(cm.status, 'approved') IN ('active','approved')
      ), tree AS (
        SELECT e.child, 1 depth FROM edges e WHERE e.parent = v_actor
        UNION ALL
        SELECT e.child, t.depth + 1 FROM tree t JOIN edges e ON e.parent = t.child
         WHERE t.depth < 20
      ) SELECT 1 FROM tree WHERE child = p_target_user_id
    ) THEN RETURN 'downline'; END IF;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.club_members actor
     WHERE actor.user_id = v_actor AND actor.club_id = p_club_id
       AND COALESCE(actor.status, 'approved') IN ('active','approved')
  ) THEN RETURN 'identity'; END IF;
  RETURN 'none';
END;
$function$
